// Illustrative presentation flows. They do not call tools or simulate live customer data.
const tones={violet:'#c9a9f1',blue:'#8fc8f2',mint:'#91d8c3',gold:'#e5bc84'};
const node=(x,y,w,h,label,title,body='',tone='violet',extra='')=>`<article class="wf-node ${extra}" style="--x:${x}%;--y:${y}%;--w:${w}%;--h:${h}%;--tone:${tones[tone]}"><span class="wf-eyebrow">${label}</span><h2>${title}</h2>${body?`<p>${body}</p>`:''}</article>`;
const wire=(d,tone='violet',delay=0,index=0)=>`<g style="--tone:${tones[tone]};--delay:${delay}s"><path class="wf-wire-base" d="${d}" marker-end="url(#wf-arrow-${tone}-${index})"/><path class="wf-wire-flow" d="${d}" pathLength="100"/><circle r="3.5"><animateMotion dur="3.8s" begin="${delay}s" repeatCount="indefinite" path="${d}"/></circle></g>`;
const wires=(paths)=>`<svg class="wf-wires" viewBox="0 0 1200 560" preserveAspectRatio="none" aria-hidden="true">${paths.map((p,i)=>`<defs><marker id="wf-arrow-${p[1]||'violet'}-${i}" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto" markerUnits="userSpaceOnUse" style="--tone:${tones[p[1]||'violet']}"><path d="M0 1L8 4.5 0 8Z"/></marker></defs>${wire(p[0],p[1],p[2],i)}`).join('')}</svg>`;
const stage=(type,html)=>`<div class="wc-flow-layout wf-${type}" data-flow="${type}"><div class="wf-stage-grid" aria-hidden="true"></div>${html}</div>`;
const ribbon=(text)=>`<div class="wf-ribbon">${text}</div>`;
const chart=()=>`<svg viewBox="0 0 420 230" class="wf-chart" aria-label="設備趨勢示意圖"><g class="wf-chart-grid"><path d="M35 25V190H400 M35 65H400 M35 105H400 M35 145H400 M120 25V190 M205 25V190 M290 25V190 M375 25V190"/></g><path class="wf-trend" d="M35 158L70 151 105 160 140 143 175 149 210 115 245 125 280 70 315 81 350 42 390 55"/><rect x="260" y="28" width="137" height="70" rx="8" class="wf-chart-focus"/><text x="38" y="218">時間</text><text x="268" y="20">變化區域</text></svg>`;
const reportPaper=()=>`<div class="wf-report-paper"><div><span>FIELD REVIEW</span><b>巡檢摘要</b></div><section><small>01 / 觀察</small><h3>趨勢變化需要留意</h3><p>彙整設備紀錄與分析結果</p></section><section><small>02 / 依據</small><h3>對照相關 SOP</h3><p>附上來源片段與查詢脈絡</p></section><section><small>03 / 下一步</small><h3>交由人員確認</h3><p>列出待查證事項與追查方向</p></section><footer>資料 × 知識 × 工作方法</footer></div>`;
const flows={
 vlm:()=>stage('vlm',`${wires([['M420 280H502','blue'],['M718 280H785','violet',.5]])}<div class="wf-image-source"><span class="wf-eyebrow">INPUT / 設備趨勢圖</span>${chart()}<div class="wf-scan-bar"></div><p>圖表、位置與視覺關係</p></div>${node(42,26,18,48,'VISUAL UNDERSTANDING','VLM','理解圖中內容<br>連結文字脈絡','violet','wf-processor')}${node(66,11,33,76,'OUTPUT / 圖像理解','從像素，到脈絡',`<span class="wf-result-row"><b>看見什麼</b>設備趨勢與變化區域</span><span class="wf-result-row"><b>如何描述</b>後段出現上升與波動</span><span class="wf-result-row"><b>保留來源</b>原圖 · 文件 · 頁碼</span>`,'mint','wf-result')}`),
 indexing:()=>stage('indexing',`${wires([['M216 146H312','blue'],['M216 375H312','violet',.4],['M540 146H585Q618 146 618 260H696','blue',.7],['M540 375H585Q618 375 618 300H696','violet',1],['M900 280H984','mint',1.3]])}${node(0,9,18,34,'TEXT','文字與段落','說明 · SOP · 表格','blue')}${node(0,50,18,34,'IMAGE','圖像與圖表','零件圖 · 流程 · 趨勢','violet')}${node(26,9,19,34,'LLM','理解文字','內容與語意脈絡','blue','wf-processor')}${node(26,50,19,34,'VLM','理解圖像','視覺描述與關係','violet','wf-processor')}${node(58,25,17,50,'EMBEDDING','知識索引','整理內容<br>建立檢索表示','mint','wf-vector-node')}${node(82,25,18,50,'KNOWLEDGE','企業知識庫','內容片段<br>來源連結','gold','wf-store')}${ribbon('文字與圖像保留共同來源，檢索時找回完整脈絡。')}`),
 retrieval:()=>stage('retrieval',`<div class="wf-query"><span>AGENT / 知識需求</span><h2>「這個部件，應該依哪份 SOP 檢查？」</h2></div>${wires([['M240 300H336','violet'],['M600 300H696','blue',.6],['M948 300H1020','mint',1]])}${node(0,32,20,45,'QUESTION','形成查詢','任務目標<br>相關上下文')}${node(28,28,22,53,'RAG RETRIEVAL','找相關知識','Vector / Hybrid<br>GraphRAG','blue','wf-processor')}${node(58,32,21,45,'EVIDENCE','帶回片段','SOP 內容<br>圖片描述 · 出處','mint')}${node(85,32,15,45,'AGENT','形成回答','根據檢索內容<br>整理與引用','gold')}${ribbon('RAG 提供依據，Agent 將依據放回工作問題。')}`),
 citations:()=>stage('citations',`${wires([['M408 280H516','violet'],['M792 280H900','blue',.7]])}${node(0,14,34,69,'ANSWER / 示意回答','檢查密封部件，<br>並對照維修規範。','<span class="wf-cite-tag">[1] 維修 SOP · 第 12 頁</span><span class="wf-cite-tag">[2] 部件圖解 · 第 8 頁</span>','violet','wf-answer-card')}${node(43,23,23,51,'RETRIEVED CONTEXT','引用片段','規範文字與圖像描述<br>保留段落、文件與頁碼','blue')}${node(75,14,25,69,'ORIGINAL SOURCE','回到原文','<span class="wf-source-line">維修 SOP / P.12</span><span class="wf-source-line">部件圖解 / P.08</span><span class="wf-source-line">版本與文件脈絡</span>','gold','wf-source-paper')}${ribbon('回答不是終點，引用讓知識可以被查核與補充。')}`),
 mission:()=>stage('mission',`<div class="wf-goal"><span class="wf-eyebrow">THE GOAL</span><h2>「幫我整理今天的<br><em>設備巡檢摘要。</em>」</h2><p>要用哪些資料？依什麼方法？交付什麼？</p></div>${wires([['M480 280H576','gold'],['M768 280H840V125H912','violet',.3],['M768 280H912','blue',.6],['M768 280H840V435H912','mint',.9]])}${node(48,29,16,43,'ORCHESTRATOR','Agent','理解 · 規劃<br>調用 · 檢視','gold','wf-agent-core')}${node(76,8,24,28,'RAG / 知識','查規範與經驗','提供任務需要的依據','violet')}${node(76,37,24,28,'SKILL / 工作能力','使用方法與工具','依任務調用資料與分析','blue')}${node(76,66,24,28,'OUTPUT / 成果','形成巡檢摘要','觀察 · 依據 · 待確認事項','mint')}`),
 skilldispatch:()=>stage('skilldispatch',`${wires([['M240 280H408','gold'],['M660 280H804V112H888','blue',.3],['M660 280H888','blue',.6],['M660 280H804V448H888','blue',.9]])}${node(0,28,20,44,'AGENT REQUEST','需要現場紀錄','依任務選擇工具<br>帶上查詢條件','gold')}${node(34,18,21,64,'WORK CAPABILITY','SKILL','工作方法<br>工具使用<br><span class="wf-skill-parts"><span>方法</span><span>工具</span><span>輸出</span></span>','blue','wf-gateway')}${node(74,3,26,30,'DATA SOURCE','企業資料庫','生產紀錄 · 歷史事件','blue')}${node(74,35,26,30,'FIELD SYSTEM','WinEdge','設備狀態 · 現場資料','mint')}${node(74,67,26,30,'ANALYSIS TOOL','分析工具','NumOps / 領域分析','violet')}`),
 returns:()=>stage('returns',`${wires([['M276 100H342Q390 100 390 230H456','blue'],['M276 268H456','mint',.4],['M276 436H342Q390 436 390 310H456','violet',.8],['M720 280H828','gold',1.2]])}${node(0,3,23,29,'DATABASE','運轉紀錄','時間 · 設備 · 事件','blue')}${node(0,34,23,29,'ANALYSIS','分析結果','趨勢 · 變化 · 關注項目','mint')}${node(0,65,23,29,'RAG','文件依據','相關 SOP · 歷史經驗','violet')}${node(38,22,22,54,'AGENT / CONTEXT','組織資訊','比對現況與規範<br>保留資料與引用脈絡','gold','wf-agent-core')}${node(69,16,31,67,'READY FOR REVIEW','可判讀的脈絡','<span class="wf-result-row"><b>發生什麼</b>整理現場觀察</span><span class="wf-result-row"><b>根據什麼</b>連回紀錄與知識</span><span class="wf-result-row"><b>還缺什麼</b>標記待確認資訊</span>','mint')}`),
 report:()=>stage('report',`${wires([['M264 168H348V260H420','blue'],['M264 392H348V300H420','violet',.5],['M672 280H780','gold',1]])}${node(0,12,22,36,'SKILL / 工具回傳','現場資料','設備紀錄 · 分析觀察','blue')}${node(0,52,22,36,'RAG / 檢索結果','工作依據','SOP · 相關經驗','violet')}${node(35,25,21,50,'AGENT','整理與分析','把觀察放回脈絡<br>形成可閱讀的結果','gold','wf-agent-core')}${reportPaper()}`),
 recipe:()=>stage('recipe',`<div class="wf-skill-book"><span class="wf-eyebrow">REUSABLE WORK METHOD</span><h2>巡檢摘要<br><em>SKILL</em></h2><p>把專家的做法，<br>變成 Agent 可使用的方法。</p><div class="wf-book-seal">METHOD · TOOLS · OUTPUT</div></div><div class="wf-recipe-steps">${[['01','輸入什麼','設備範圍、時間區間、巡檢目標'],['02','依序怎麼做','查規範 → 取紀錄 → 比對與整理'],['03','產出什麼','觀察、依據、待確認事項']].map(a=>`<article><b>${a[0]}</b><div><h2>${a[1]}</h2><p>${a[2]}</p></div></article>`).join('')}</div>`),
 execution:()=>stage('execution',`<div class="wf-execution-header"><span>AGENT 執行中</span><h2>載入「巡檢摘要」SKILL</h2><p>工作方法已定義，能力依步驟調用。</p></div>${wires([['M216 310H312','mint'],['M516 310H612','violet',.6],['M816 310H912','blue',1.2]])}${node(0,35,18,46,'01 / SKILL','讀取方法','確認任務<br>與輸出格式','mint','wf-step-1')}${node(26,35,17,46,'02 / RAG','查找規範','檢索相關 SOP<br>與來源','violet','wf-step-2')}${node(51,35,17,46,'03 / TOOLS','取得紀錄','連接系統工具<br>回傳現況','blue','wf-step-3')}${node(76,35,24,46,'04 / AGENT','產出摘要','綜合資料與知識<br>依指定格式交付','gold','wf-step-4')}${ribbon('SKILL 說明怎麼做；Agent 負責依任務調用、整理與檢視。')}`),
 orchestration:()=>stage('orchestration',`${wires([['M348 280H468','violet'],['M852 280H732','blue',.6],['M600 140V218','mint',.3],['M600 375V431','gold',1]])}${node(36,0,28,25,'WORK OBJECTIVE','整理設備巡檢摘要','','gold')}${node(0,31,29,41,'RAG / 知識支援','找得到依據','企業文件 · 圖文知識 · 來源','violet')}${node(39,39,22,28,'ORCHESTRATOR','Agent','理解 → 規劃 → 調用 → 檢視','gold','wf-agent-core')}${node(71,31,29,41,'SKILL / 工作能力','有方法，也有工具','作業步驟 · 工具調用 · 輸出要求','blue')}${node(31,77,38,22,'WORK OUTPUT','有依據、可使用的工作結果','','gold','wf-output-strip')}`),
 applications:()=>stage('applications',`<div class="wf-app-lanes">${[['客服維修','拿到部件圖，如何查修？','維修查詢 SKILL','RAG 圖文知識','圖文答覆','附上部件圖解與維修依據','violet'],['新人培訓','第一次做，從哪裡開始？','SOP 導讀 SKILL','RAG 規範與經驗','流程導讀','依問題找到步驟與注意事項','blue'],['現場巡檢','今天有哪些變化？','巡檢摘要 SKILL','系統工具 + RAG 規範','巡檢摘要','整理觀察、依據與待確認事項','mint']].map((a,i)=>`<article style="--tone:${tones[a[6]]};--i:${i}"><div class="wf-app-question"><span>0${i+1} / ${a[0]}</span><h2>${a[1]}</h2></div><i class="wf-inline-flow"></i><div class="wf-app-method"><span>AGENT</span><h3>${a[2]}</h3><p>${a[3]}</p></div><i class="wf-inline-flow wf-output-flow" data-reveal-at="1"></i><div class="wf-app-result" data-reveal-at="1"><span>OUTPUT</span><h2>${a[4]}</h2><p>${a[5]}</p></div></article>`).join('')}</div>`)
};
export function winChatFlow(scene){return flows[scene]?.();}
